function build(M) {
  const W = 1.6, H = 0.8;
  const body = M.box(W, H, W, 0);
  const strands = [];
  for (let i = -3; i <= 3; i++) {
    const t = i * 0.22;
    for (const s of [1, -1]) {
      strands.push(M.pipe([t - 0.2, 0.05, s * 0.81], [t + 0.2, 0.75, s * 0.81], 0.012, 6));
      strands.push(M.pipe([t + 0.2, 0.05, s * 0.81], [t - 0.2, 0.75, s * 0.81], 0.012, 6));
      strands.push(M.pipe([s * 0.81, 0.05, t - 0.2], [s * 0.81, 0.75, t + 0.2], 0.012, 6));
      strands.push(M.pipe([s * 0.81, 0.05, t + 0.2], [s * 0.81, 0.75, t - 0.2], 0.012, 6));
    }
  }
  const rim = [];
  for (const s of [1, -1]) {
    rim.push(M.pipe([-0.82, H, s * 0.82], [0.82, H, s * 0.82], 0.05, 12));
    rim.push(M.pipe([s * 0.82, H, -0.82], [s * 0.82, H, 0.82], 0.05, 12));
  }
  const base = M.box(W + 0.06, 0.06, W + 0.06, -0.02);
  const cables = [];
  for (const sx of [1, -1]) for (const sz of [1, -1]) {
    cables.push(M.pipe([sx * 0.78, 0.2, sz * 0.78], [sx * 0.5, 1.2, sz * 0.5], 0.015, 8));
  }
  return [
    {material: "orange", look: "solid", mesh: body},
    {material: "gold", look: "solid", mesh: M.merge(strands)},
    {material: "red", look: "solid", mesh: M.merge(rim)},
    {material: "dark_steel", look: "solid", mesh: base},
    {material: "steel", look: "solid", mesh: M.merge(cables)}
  ];
}

