    steel.push(M.T(body, {pos: [x, -0.45, 0]}));
    dark.push(M.T(M.torus(0.11, 0.008, 32, 6), {pos: [x, -0.43, 0]}));
    dark.push(M.T(M.torus(0.11, 0.008, 32, 6), {pos: [x, 0.1, 0]}));
    dark.push(M.T(M.cyl(0.025, 0.06, 16, 0.27), {pos: [x, 0, 0]}));
    dark.push(M.T(M.box(0.06, 0.025, 0.025, 0.3), {pos: [x, 0, 0]}));
    red.push(M.T(M.cyl(0.04, 0.02, 20, 0.33), {pos: [x, 0, 0]}));
