    {material: "dark_steel", look: "solid", mesh: M.merge(dark)},
    {material: "red", look: "solid", mesh: M.merge(red)},
    {material: "dark_steel", look: "solid", mesh: M.merge(blk)}
  ];
}

function build(M) {
  const prof = [[0.75,0],[0.8,0.2],[0.88,0.5],[0.95,0.8],[1.0,1.0],[0.97,1.0],[0.92,0.8],[0.85,0.5],[0.77,0.2],[0.72,0.02],[0.72,0]];
  const cloth = M.lathe(prof, 48);
  const seams = [];
  for (let i = 0; i < 16; i++) {
    const a = i / 16 * Math.PI * 2, c = Math.cos(a), s = Math.sin(a);
    seams.push(M.pipe([0.765*c,0.02,0.765*s],[0.81*c,0.25,0.81*s],0.012,6));
    seams.push(M.pipe([0.81*c,0.25,0.81*s],[0.89*c,0.52,0.89*s],0.012,6));
    seams.push(M.pipe([0.89*c,0.52,0.89*s],[1.01*c,1.0,1.01*s],0.012,6));
  }
  const tapes = M.merge([
    M.T(M.torus(0.75, 0.03, 48, 8), {pos:[0,0,0]}),
    M.T(M.torus(0.99, 0.025, 48, 8), {pos:[0,1,0]}),
    ...Array.from({length:16},(_,i)=>{const a=i/16*Math.PI*2;return M.T(M.sphere(0.035,8,6),{pos:[0.75*Math.cos(a),0,0.75*Math.sin(a)]});})
  ]);
  const stitch = M.T(M.torus(0.86, 0.01, 48, 6), {pos:[0,0.45,0]});
  return [
    {material:"dark_steel", look:"solid", mesh:cloth},
    {material:"orange", look:"solid", mesh:M.merge([...seams, stitch])},
    {material:"steel", look:"solid", mesh:tapes}
  ];
}

function build(M) {
  const prof = [];
  const N = 30;
  for (let i = 0; i <= N; i++) {
    const t = i / N;
    const y = t * 3.5;
    let r;
    if (y < 2.3) { const u = y / 2.3; r = 0.5 + 2.5 * Math.sin(u * Math.PI / 2); }
    else { const u = (y - 2.3) / 1.2; r = 3.0 * Math.sqrt(Math.max(0, 1 - u * u)); }
    prof.push([r, y]);
  }
  prof[prof.length - 1][0] = 0;
  const gores = 12, segPer = 4;
  const mats = ["red", "orange", "blue"];
  const groups = [[], [], []];
  for (let g = 0; g < gores; g++) {
    const m = M.mesh();
    const a0 = g / gores * Math.PI * 2;
    for (let i = 0; i <= N; i++) {
      for (let j = 0; j <= segPer; j++) {
        const a = a0 + j / segPer * Math.PI * 2 / gores;
        const [r, y] = prof[i];
        const c = Math.cos(a), s = Math.sin(a);
        M.vert(m, [r * c, y - 1.75, r * s], [c, 0.2, s]);
      }
    }
    const W = segPer + 1;
    for (let i = 0; i < N; i++) for (let j = 0; j < segPer; j++) {
      const a = i * W + j, b = a + 1, c = a + W, d = c + 1;
      m.i.push(a, c, b, b, c, d);
    }
    groups[g % 3].push(m);
  }
  const seams = [];
  for (let g = 0; g < gores; g++) {
    const a = g / gores * Math.PI * 2;
    for (let i = 0; i < N; i++) {
      const p = (k) => [prof[k][0] * 1.005 * Math.cos(a), prof[k][1] - 1.75, prof[k][0] * 1.005 * Math.sin(a)];
      seams.push(M.pipe(p(i), p(i + 1), 0.025, 6));
    }
  }
  seams.push(M.T(M.torus(0.5, 0.05, 32, 8), { pos: [0, -1.75, 0] }));
  seams.push(M.T(M.torus(2.95, 0.04, 48, 6), { pos: [0, 0.55, 0] }));
  return [
    { material: "red", look: "solid", mesh: M.merge(groups[0]) },
    { material: "orange", look: "solid", mesh: M.merge(groups[1]) },
    { material: "blue", look: "solid", mesh: M.merge(groups[2]) },
    { material: "white", look: "solid", mesh: M.merge(seams) }
  ];
}

function build(M) {
  const cap = M.lathe([[0,0.2],[0.3,0.19],[0.55,0.15],[0.72,0.08],[0.75,0.03],[0.72,0.03],[0.55,0.11],[0.3,0.155],[0,0.165]], 40);
  const rim = M.T(M.torus(0.73, 0.025, 40, 8), {pos:[0,0.04,0]});
  const seams = [];
  for (let i = 0; i < 8; i++) {
    const a = i * Math.PI / 4;
    seams.push(M.pipe([0,0.2,0],[0.74*Math.cos(a),0.04,0.74*Math.sin(a)],0.008,6));
  }
  const cords = [];
  for (let i = 0; i < 12; i++) {
    const a = i * Math.PI / 6 + 0.1;
    cords.push(M.pipe([0.72*Math.cos(a),0.04,0.72*Math.sin(a)],[0.5*Math.cos(a),-0.1,0.5*Math.sin(a)],0.006,5));
    cords.push(M.pipe([0.5*Math.cos(a),-0.1,0.5*Math.sin(a)],[0,-0.1,0],0.005,5));
  }
  const hub = M.cyl(0.05, 0.04, 16, -0.12);
  const crown = M.T(M.torus(0.12, 0.015, 24, 6), {pos:[0,0.2,0]});
  return [
    {material:"white", look:"solid", mesh:M.merge([cap])},
    {material:"red", look:"solid", mesh:M.merge([rim, crown, ...seams])},
    {material:"dark_steel", look:"solid", mesh:M.merge([...cords, hub])}
  ];
}
